import{_ as r,l as i,o as e,c as n,v as t,p as l,x as o,d as c,i as p,S as m}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"共识与 2PC","description":"","frontmatter":{"title":"共识与 2PC","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/consensus-vs-2pc.md","filePath":"cs/consensus-vs-2pc.md","lastUpdated":1789023840000}'),P={name:"cs/consensus-vs-2pc.md"};function d(C,a,h,E,_,A){const s=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="共识与-2pc" tabindex="-1">共识与 2PC <a class="header-anchor" href="#共识与-2pc" aria-label="Permalink to &quot;共识与 2PC&quot;">​</a></h1><div class="epigraph"><p>两阶段提交让所有资源管理器同提交或同中止，但协调者崩溃会阻塞。共识复制的是决策日志，换主可以继续；2PC 复制的不是那条日志。</p><footer>—— 据 Gray and Reuter, Transaction Processing；Lamport, Paxos Made Simple；Skeen, Nonblocking Commit Protocols 整理</footer></div><p>上一课<a href="/cs/pbft">PBFT</a>把法定人数决策做到撒谎档。缺口是<strong>事务提交协议常被误叫共识</strong>：2PC 的参与者对「commit/abort」要一致，但经典 2PC 有单点阻塞，不满足<a href="/cs/flp-impossibility">FLP</a>语境下「正确节点终决定」——它根本没打算在协调者死时终止。本课拆开。不重写 prepare/accept。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>2PC：协调者问 canCommit，全部是则 commit，否则 abort。参与者在准备后进入不确定态，必须等协调者。协调者在发出 commit 前崩溃：参与者阻塞。这是原子提交，规格是「全员同结果」，假设是崩溃恢复+最终协调者回来或人工。</p><p>共识（Paxos）：多数派活着即可选定值，少数派阻塞不影响已选定值的学习者。缺口：原子提交在存在故障时有已知困难（Skeen 非阻塞提交需要更多轮与更多活节点假设）。把 2PC 当 Paxos 会在协调者死时把整个事务卡住，还以为「有共识」。</p><p><span class="marginnote">Gray 的事务教材把 2PC 当恢复协议。Paxos-Commit 一类工作用共识选 commit/abort，消除单协调者阻塞，那是混合，不是经典 2PC。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>需要跨分片原子：要么阻塞式 2PC（短事务、协调者高可用），要么把提交记录写进<a href="/cs/replicated-state-machine">RSM</a>（协调者本身是多数派）。需要给配置/锁一个值：直接共识，不要 2PC。</p>',9)),(e(),l(m,null,{default:o(()=>[p(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACM%5B%22%E5%8E%9F%E5%AD%90%E6%8F%90%E4%BA%A4%3A%20%E5%85%A8%E5%91%98%E5%90%8C%20commit%2Fabort%22%5D%20--%3E%20TPC%5B%222PC%3A%20%E5%8D%8F%E8%B0%83%E8%80%85%E5%8F%AF%E9%98%BB%E5%A1%9E%22%5D%0A%20%20ACM%20--%3E%20PC%5B%22Paxos-Commit%20%E7%AD%89%22%5D%0A%20%20CONS%5B%22%E5%85%B1%E8%AF%86%3A%20%E5%A4%9A%E6%95%B0%E6%B4%BE%E9%80%89%E5%AE%9A%E4%B8%80%E5%80%BC%22%5D%20--%3E%20LOG%5B%22RSM%20%E6%97%A5%E5%BF%97%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>3PC 减少部分阻塞，在异步网络仍有坑；本课点名，不展开状态表。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>2PC 的「多数」不是法定人数相交：它要<strong>全体</strong>准备成功才提交，一个慢盘就能中止或拖死。共识的多数是为了在 \\(f\\lt n/2\\) 崩溃下仍选定。对象不同：2PC 对象是事务结局；Paxos 对象是槽里的字节。</p><p>数据库课的事务与 WAL 仍在：2PC 是跨资源管理器的补丁。分布式课到这里才把它和复制日志分开，避免「我们用了 2PC 所以线性一致」——2PC 不给寄存器线性一致，只给参与者原子结局，且可阻塞。</p><p>本课不重写隔离级别。也不把 Saga 补偿当 2PC（后课系统模式）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不画 2PC 全部超时状态。不引入 XA 接口清单。后课默认：阻塞原子提交 ≠ 共识；要故障下仍前进，把决策放进 Paxos/Raft 日志。领导者选举下一课处理「谁当协调者/主」的脑裂，那是另一坑。</p><p>全员同意比多数派同意更脆。脆的协议不能靠改名变强壮。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>2PC：原子提交，协调者崩溃阻塞。</li><li>共识：多数派选定值，换提议者可继续。</li><li>高可用提交 = 用共识复制 commit 决策，不是裸 2PC。</li><li>出处：Gray and Reuter；Lamport 2001；Skeen 非阻塞提交。</li></ul>',10))])}const b=r(P,[["render",d]]);export{f as __pageData,b as default};
